// Parse tickets and emit one item per ticket so we can fetch threads individually
const raw = $input.first().json.data;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { error: 'Parse error', raw } }];
}

const tickets = parsed.data || [];
if (tickets.length === 0) {
  return [{ json: { skip: true, message: 'No open tickets' } }];
}

return tickets.map(t => ({
  json: {
    ticketId: t.id,
    ticketNumber: t.ticketNumber,
    subject: t.subject
  }
}));

// ============================================================
// CONFIGURE: Your agent names and their Cliq chat IDs
// ============================================================
const AGENTS = [
  { name: 'John Smith',   cliqId: 'john.smith@example.com',   deskId: '111111111' },
  { name: 'Jane Doe',     cliqId: 'jane.doe@example.com',     deskId: '222222222' },
  { name: 'Bob Wilson',   cliqId: 'bob.wilson@example.com',   deskId: '333333333' }
];

const ORG_ID = 'YOUR_ORG_ID';
const CLIQ_API_BASE = 'https://cliq.zoho.eu/api/v2';
// ============================================================

// Track already-notified mentions to avoid spam
const staticData = $getWorkflowStaticData('global');
if (!staticData.notified) staticData.notified = {};

const ticketInfo = $('Parse Tickets').first().json;
const raw = $input.first().json.data;
let threads;
try {
  threads = JSON.parse(raw).data || [];
} catch (e) {
  return [{ json: { skip: true, error: 'Thread parse error' } }];
}

const results = [];

for (const thread of threads) {
  const content = (thread.content || '').replace(/<[^>]*>/g, ' ').toLowerCase();
  const summary = (thread.summary || '').toLowerCase();
  const text = content + ' ' + summary;

  for (const agent of AGENTS) {
    const nameLower = agent.name.toLowerCase();
    const firstName = nameLower.split(' ')[0];

    if (text.includes(nameLower) || text.includes(firstName)) {
      const key = `${ticketInfo.ticketId}_${thread.id}_${agent.deskId}`;
      if (staticData.notified[key]) continue;

      staticData.notified[key] = Date.now();
      results.push({
        json: {
          ticketId: ticketInfo.ticketId,
          ticketNumber: ticketInfo.ticketNumber,
          subject: ticketInfo.subject,
          threadId: thread.id,
          mentionedAgent: agent.name,
          mentionedAgentCliqId: agent.cliqId,
          mentionedAgentDeskId: agent.deskId,
          orgId: ORG_ID,
          cliqApiBase: CLIQ_API_BASE,
          snippet: text.substring(0, 200)
        }
      });
    }
  }
}

// Clean old entries (older than 24h)
const cutoff = Date.now() - 86400000;
for (const [k, v] of Object.entries(staticData.notified)) {
  if (v < cutoff) delete staticData.notified[k];
}

if (results.length === 0) {
  return [{ json: { skip: true, message: 'No new mentions found' } }];
}

return results;

